-- ==============================================================

function ParkourGameRunner:__init()
    self.tickDuration = 0.1
    self.state = 0 -- 0:未开始 1:开始 2:暂停
    ---@type Track[]
    self.tracks = {}
    self.mapName = nil
end



---@param gameType_ number @ ParkourGameUtil.GameType
---@param mapName_ string @ "Level1"
function ParkourGameRunner:InitForNormal(gameType_, mapName_)
    self:SetGameType( gameType_ )

    ---@type ParkourFactory
    self.factory = ParkourFactory.New(self.controller.transform:Find('PoolRoot'))

    ---@type TrackMapReader
    self.trackMapReader =  TrackMapReader.New(self.factory, tostring(mapName_))

    self:_DoInit()
end



---@param gameType_ number @ ParkourGameUtil.GameType
---@param mapVos_ table[] 
function ParkourGameRunner:InitForInfinity(gameType_, mapVos_)
    self:SetGameType( gameType_ )

    ---@type ParkourFactory
    self.factory = ParkourFactory.New(self.controller.transform:Find('PoolRoot'))

    ---@type TrackMapReaderInfinity
    self.trackMapReader =  TrackMapReaderInfinity.New( self.factory, mapVos_ )

    self:_DoInit()
end



function ParkourGameRunner:_DoInit()

    parkourInput.runEvent = 0 -- role idle

    ---@type ParkourScoreboard
    self.scoreboard = ParkourScoreboard.New()
    self:_ReadParams()
    
    ---@type ParkourPlayerController
    self.player = Mgr.player
    self.player:SetMaxHp(ParkourGameUtil.Params.CatData.NormalLevelHp)

    ---@type ParkourBoss
    self.boss = CfUtils.GetLuaScr(self.controller.transform:Find("Track3/PlayerRoot/Boss"), "Game.Activity.ParkourGame.MainGame.ParkourBoss")
    Mgr.boss = self.boss

    self.boss:Init(self.trackMapReader:CrowData(),self.factory)
    self.entitys  = {}
    table.insert(self.entitys,self.player)
    table.insert(self.entitys,self.boss)
    
    
    --屏幕后处理
    self.camera  = URPCameraController.mainCamera
    ---@type VignetteHelper
    self.vignetteHelper = self.camera.gameObject:AddComponent(typeof(CS.VignetteHelper))
    self.vignetteHelper.vignetteState = 1
    self.vignetteHelper.intensity = 0.45
    self.vignetteHelper.smoothness = 0.3
    
    
    --绑定update
    local behaviourAction = CfUtils.GetOrAddComponent(self.controller,typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.FixedUpdateAction = Bind(self,self.FixedUpdate)
        behaviourAction.UpdateAction = Bind(self,self.Update)
    end

    ---创建轨道
    ---@type UnityEngine.Transform
    local track1 = self.controller.transform:Find('Track1')
    local imgPaths = self.trackMapReader:ImgPaths()
    local bgImgTrack = self.factory:CreateTrack1(track1,2, 28.8,self.track1Speed,imgPaths)
    table.insert(self.tracks, bgImgTrack)
    
    local track2 = self.controller.transform:Find('Track2')
    local middlePrefabs = self.trackMapReader:MiddlePrefabs()
    local middleTrack = self.factory:CreateTrack2(track2, middlePrefabs, 2,20, self.track2Speed)
    table.insert(self.tracks, middleTrack)
    
    local track3 = self.controller.transform:Find('Track3')
    local interactionTrack = self.factory:CreateInteractionTrackSegment(track3, 3,ParkourGameUtil.InteractionTrackWidth, self.trackMapReader,self.track3Speed)
    table.insert(self.tracks, interactionTrack)
    
    --其他
    ---@type ParkourParticleMgr
    local ParkourParticleMgr = import("Game.Activity.ParkourGame.MainGame.ParkourParticleMgr")
    self.particleMgr = ParkourParticleMgr.New(self.controller.transform:Find("ParticleRoot"))

      
    if Application.isEditor then
        ---@type TestGame
        local TestGame = import("Game.Activity.ParkourGame.MainGame.Test.TestGame") -- !! debug
        self.TestGame =  TestGame.New()
    end

    --- ===
    CoStop(self.co_1)
    self.co_1 = CoStart(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 1.2 ))
        self:StartGame()
    end)
end





function ParkourGameRunner:OnDestroy()
    self:Delete()
end

function ParkourGameRunner:__delete()
    CoStop(self.co_1)
    self:FinishGame()
    
    if self.vignetteHelper then
        GameObject.Destroy(self.vignetteHelper)
    end
    
    for _, track in ipairs(self.tracks) do
        track:Delete()
    end
    
    Time.timeScale = 1
    self.particleMgr:Delete()
end


function ParkourGameRunner:Update()
    if self.state == 1 then

        if isNotNull(self.TestGame) then 
            self.TestGame:Update() -- !! debug
        end 
        
        for _, ent in ipairs(self.entitys) do
            ent:Update()
        end
    end
end

function ParkourGameRunner:FixedUpdate()
    if self.state == 1 then
        for _, track in ipairs(self.tracks) do
            track:Tick(Time.fixedDeltaTime)
        end
        
        self:_CheckReachEnd()

        for _, ent in ipairs(self.entitys) do
            if ent.FixedUpdate then
                ent:FixedUpdate()
            end
        end

    end
end


