---@param gameType_ number @ ParkourGameUtil.GameType
function ParkourGameRunner:SetGameType(gameType_) --1:普通 2:无尽模式
    self.gameType = gameType_
end


function ParkourGameRunner:_ReadParams()
    local luaParams = CfUtils.GetOrAddComponent(self.controller.gameObject, typeof(LuaParameters))
    self.track1Speed = LuaParametersReader.Read(luaParams, "track1Speed", LuaParametersReader.Type.Float)
    self.track2Speed = LuaParametersReader.Read(luaParams, "track2Speed", LuaParametersReader.Type.Float)
    self.track3Speed = LuaParametersReader.Read(luaParams, "track3Speed", LuaParametersReader.Type.Float)
    
    ParkourGameUtil.Params.InvincibleDashSpeedRatio = LuaParametersReader.Read(luaParams, "InvincibleDashSpeedRatio", LuaParametersReader.Type.Float)
    ParkourGameUtil.Params.MagnetRange = LuaParametersReader.Read(luaParams, "MagnetRange", LuaParametersReader.Type.Float)
    
    ParkourGameUtil.Params.CatData.NormalLevelHp = ParkourGameUtil.GetVoParamValue(ParkourGameUtil.VoParamsId.MainLevelCatHp)
    ParkourGameUtil.Params.CatData.FreeLevelHp = ParkourGameUtil.GetVoParamValue(ParkourGameUtil.VoParamsId.FreeLevelCatHp)
    ParkourGameUtil.Params.BossData.Hp = ParkourGameUtil.GetVoParamValue(ParkourGameUtil.VoParamsId.CrowHp)
    local crowData = self.trackMapReader:CrowData()
    ParkourGameUtil.Params.BossData.FirstAttckType = crowData.firstAttackType
    ParkourGameUtil.Params.BossData.AppearCD = crowData.appearCD
    ParkourGameUtil.Params.BossData.AttackCD = crowData.attackCD
    
    ParkourGameUtil.Params.InvincibleDashTime = LuaParametersReader.Read(luaParams, "InvincibleDashTime", LuaParametersReader.Type.Float)
    ParkourGameUtil.Params.MagnetTime = LuaParametersReader.Read(luaParams, "MagnetTime", LuaParametersReader.Type.Float)
    ParkourGameUtil.Params.BossCountDownDelayTime = LuaParametersReader.Read(luaParams, "BossCountDownDelayTime", LuaParametersReader.Type.Float)

    if self.gameType == ParkourGameUtil.GameType.Normal then 
        self._levelLength = self.trackMapReader:GetLevelLength()
    end
end


function ParkourGameRunner:_CheckReachEnd()
    if self.gameType ~= ParkourGameUtil.GameType.Normal then 
        return
    end 
    ---
    if self.tracks[3].moveDistance >= self._levelLength then
        --printError("抵挡终点")
        parkourInput.runEvent = 0 -- role idle
        self.state = 0
        Mgr.player:OnSuccess()
    end
end

-- only in Normal Mode:
function ParkourGameRunner:Progress()
    return self.tracks[3].moveDistance / self._levelLength
end


function ParkourGameRunner:StartGame()
    Events.Broadcast(ParkourGameUtil.Events.GameStart)
    self.boss:StartCountDown()
    self.state = 1

    parkourInput.runEvent = 1 -- role run
end


function ParkourGameRunner:IsStartGame()
    return self.state > 0
end


function ParkourGameRunner:PauseGame()
    print("ParkourGameRunner:PauseGame")
    self.state = 2
    Physics.autoSimulation = false
end

function ParkourGameRunner:ResumeGame()
    print("ParkourGameRunner:ResumeGame")
    self.state = 1
    Physics.autoSimulation = true
end

function ParkourGameRunner:FinishGame()
    self.state = 0
end

function ParkourGameRunner:Reset()
    print("ParkourGameRunner:Reset")
    self:FinishGame()
    self.trackMapReader:Reset()
    self.scoreboard:Reset()
    for _, track in ipairs(self.tracks) do
        track:Reset()   
    end
    
    self:_ReadParams()
    self.tracks[1]:SetSpeed(self.track1Speed)
    self.tracks[2]:SetSpeed(self.track2Speed)
    self.tracks[3]:SetSpeed(self.track3Speed)
    
    self.player:Reset()
end


---@return InteractionTrackSegment[]
function ParkourGameRunner:GetInteractionTrackSegments()
    return self.tracks[3].trackSegments
end


function ParkourGameRunner:MulTrackSpeed(multiplier)
    for i, track in ipairs(self.tracks) do
        track:SetSpeed(self["track"..i.."Speed"] * multiplier)
    end
end





return ParkourGameRunner
